+  }
+
+  if (!dead) drawScarf(f, pal, bob, st);
+  if (f.kind === 'boss' && !dead) drawCape(f, pal, bob);
+
+  // Legs.
+  const hip = -18 + bob * 0.25 + crouch * 0.4;
+  let footA = { x: -4, y: 0 };
