+    ctx.strokeStyle = pose.trailColor + alphaTrail + ')';
+    ctx.lineWidth = pose.trailWidth;
+    ctx.beginPath();
+    ctx.arc(0, 0, 27, a.swingStart, end);
+    ctx.stroke();
+    ctx.strokeStyle = 'rgba(255,255,255,' + alphaTrail * 0.72 + ')';
