+    ctx.strokeStyle = `rgba(142,244,234,${0.24 * pulse})`;
+    ctx.lineWidth = 5;
+    ctx.beginPath();
+    ctx.arc(9, -27 + bob + crouch, 17, -1.25, 1.2);
+    ctx.stroke();
+    ctx.globalAlpha = alpha;
+  }
+
+  ctx.restore();
+
+  ctx.restore();
+}
+
+function drawFighterStatus(f, game) {
