import pw from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.js';
const { chromium, devices } = pw;
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
const context = await browser.newContext({ ...devices['iPhone 13'], viewport: { width: 390, height: 844 } });
const page = await context.newPage();
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await page.tap('#startBtn');
await page.waitForTimeout(1600);
// Move toward the first enemy.
await page.locator('[data-action="right"]').dispatchEvent('pointerdown', { pointerId: 1, pointerType: 'touch', isPrimary: true });
await page.waitForTimeout(1500);
await page.locator('[data-action="right"]').dispatchEvent('pointerup', { pointerId: 1, pointerType: 'touch', isPrimary: true });
const before = await page.evaluate(() => ({
  x: Math.round(window.__blade.game.player.x),
  hp: window.__blade.game.enemies[0]?.hp,
}));
for (let i = 0; i < 5; i++) {
  await page.locator('[data-action="attack"]').tap();
  await page.waitForTimeout(330);
}
await page.locator('[data-action="parry"]').tap();
await page.waitForTimeout(200);
await page.locator('[data-action="dodge"]').tap();
await page.waitForTimeout(300);
const after = await page.evaluate(() => ({
  x: Math.round(window.__blade.game.player.x),
  hp: window.__blade.game.enemies[0]?.hp,
  playerState: window.__blade.game.player.state,
  score: window.__blade.game.score,
  errors: document.querySelector('#endScreen').className,
}));
await page.screenshot({ path: '/tmp/opencode/mobile_verified.png' });
console.log({ before, after, errors });
await browser.close();

