import pw from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.js';
const { chromium } = pw;
const browser = await chromium.launch({headless:true, args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1280,height:720}});
const errors=[]; page.on('pageerror',e=>errors.push(e.message)); page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
await page.goto('http://localhost:3002',{waitUntil:'networkidle'});
await page.click('#startBtn'); await page.waitForTimeout(1200);
// Force safe boss duel.
await page.evaluate(()=>{
  const g=window.__blade.game;
  g.enemies=[]; g.startWave(4);
  g.player.hp=100;
});
await page.waitForTimeout(1300);
await page.evaluate(()=>{
  const g=window.__blade.game, p=g.player, e=g.enemies[0];
  e.spawnT=0; e.x=p.x+42; e.facing=-1; p.facing=1; e.hp=1; e.state='idle'; e.stateT=0; e.attackCd=999; e.parryCd=999; e.dodgeCd=999; e.jumpCd=999; p.state='idle'; p.stateT=0; p.attackQueue=0;
});
await page.keyboard.press('KeyJ');
await page.waitForTimeout(500);
console.log('after attack', await page.evaluate(()=>({state:window.__blade.game.state, ws:window.__blade.game.waveState, score:window.__blade.game.score, p:{hp:window.__blade.game.player.hp,state:window.__blade.game.player.state}, es:window.__blade.game.enemies.map(e=>({dead:e.dead,state:e.state,hp:e.hp})), banner:window.__blade.game.banner?.title})));
await page.waitForTimeout(3800);
console.log('after wait', await page.evaluate(()=>({state:window.__blade.game.state, ws:window.__blade.game.waveState, end:!document.querySelector('#endScreen').classList.contains('hidden'), endTitle:document.querySelector('#endTitle').textContent, ending:window.__blade.game.ending, timer:window.__blade.game.endTimer, p:{hp:window.__blade.game.player.hp,state:window.__blade.game.player.state}})));
await page.screenshot({path:'/tmp/opencode/boss_victory.png'});
// Now direct death timing.
await page.evaluate(()=>{ window.__blade.start(); });
await page.waitForTimeout(1200);
await page.evaluate(()=>{ const g=window.__blade.game; g.player.hp=1; g.player.die(g); });
for (let i=0;i<8;i++){ await page.waitForTimeout(350); const s=await page.evaluate(()=>({state:window.__blade.game.state,ending:window.__blade.game.ending,timer:window.__blade.game.endTimer,hp:window.__blade.game.player.hp,dead:window.__blade.game.player.dead,paused:window.__blade.game.paused})); console.log(i,s); }
console.log('errors',errors);
await browser.close();

