const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await page.click('#startBtn');
await page.waitForTimeout(800);

const report = await page.evaluate(() => {
  const g = window.__blade.game;
  const out = {};
  const kinds = ['ronin', 'ninja', 'brute', 'boss'];
  for (const kind of kinds) {
    const waveIndex = { ronin: 0, ninja: 2, brute: 3, boss: 4 }[kind];
    window.__blade.wave(waveIndex);
    const e = g.enemies[0];
    const styles = new Set();
    const patterns = new Set();
    for (let i = 0; i < 120; i++) {
      e.startEnemyPattern(g, i % 2 ? 35 : 95);
      styles.add(e.attack.style);
      patterns.add(e.enemyPattern.join('>'));
    }
    out[kind] = { styles: [...styles], patterns: [...patterns] };
  }
  // Hitbox: a side cut reaches behind farther than a thrust.
  const p = g.player, e = g.enemies[0];
  p.x = 400; e.x = 388; // 12 px behind the player
  const side = p.inHitbox(e, { range: 64, height: 38, backReach: 18 });
  const thrust = p.inHitbox(e, { range: 86, height: 28, backReach: 4 });
  e.x = 470; // 70 px in front: thrust reaches, side does not
  const sideFront = p.inHitbox(e, { range: 64, height: 38, backReach: 18 });
  const thrustFront = p.inHitbox(e, { range: 86, height: 28, backReach: 4 });
  out.hitbox = { sideBehind: side, thrustBehind: thrust, sideFront, thrustFront };
  return out;
});
console.log(JSON.stringify(report, null, 2));
console.log('errors', errors);
await browser.close();
