const game = new Game();
let lastFrame = performance.now();

function loop(now) {
  const dt = clamp((now - lastFrame) / 1000, 0, 0.05);
  lastFrame = now;

  input.pollGamepad();
  game.handleGlobalInput();
  if (game.state === 'playing' && !game.paused) game.update(dt);
  else game.updateAmbient(dt);

  render(game);
  sound.updateMusic();
  input.endFrame();
  requestAnimationFrame(loop);
}

requestAnimationFrame(loop);

