    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.arc(9, -27 + bob + crouch, 17, -1.25, 1.2);
    ctx.stroke();
    ctx.globalAlpha = alpha;
  }

  ctx.restore();

  ctx.restore();
}

