Simpler: use `ctx.lineTo` but smooth via draw with quadratic between midpoints. Let's implement function:
```js
function smoothRidge(points, offsetX, offsetY) {
  ctx.beginPath();
  ctx.moveTo(points[0].x+offsetX, points[0].y+offsetY);
  for (let i=1;i<points.length-1;i++){
    const p=points[i], n=points[i+1];
    const mx=(p.x+n.x)/2, my=(p.y+n.y)/2;
    ctx.quadraticCurveTo(p.x+offsetX, p.y+offsetY, mx+offsetX, my+offsetY);
  }
  const last=points[points.length-1];
  ctx.lineTo(last.x+offsetX,last.y+offsetY);
}
